dashboard.definition:
{
    "title": "Segmentation Operations",
    "description": "Summarize segment health, policy alignment, and areas needing investigation.",
    "inputs": {
        "input_time_range": {
            "options": {
                "defaultValue": "-24h,now,1h",
                "showAdvanced": true,
                "selections": [
                    {
                        "value": "-4h,now,30m",
                        "label": "4h"
                    },
                    {
                        "value": "-24h,now,1h",
                        "label": "24h"
                    },
                    {
                        "value": "-48h,now,2h",
                        "label": "48h"
                    },
                    {
                        "value": "-7d@d,now,1d",
                        "label": "7d"
                    },
                    {
                        "value": "-30d@d,now,1d",
                        "label": "30d"
                    }
                ],
                "token": "time_tok"
            },
            "title": "Time range",
            "type": "input.simpleTimePicker"
        }
    },
    "defaults": {
        "visualizations": {
            "global": {
                "showLastUpdated": true,
                "showProgressBar": true
            }
        }
    },
    "visualizations": {
        "viz_header_bg": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#1c2738",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 10
            }
        },
        "viz_header_icon": {
            "type": "splunk.image",
            "title": "Segmentation Operations",
            "options": {
                "preserveAspectRatio": true,
                "src": "/static/app/splunk-cisco-dashboards/images/nav-icons/Globe.svg"
            }
        },
        "viz_header": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "markdown": "# Segmentation Operations\nSummarize segment health, policy alignment, and areas needing investigation\\."
            }
        },
        "viz_card_01_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_01_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**SGT Activity by Site**"
            }
        },
        "viz_card_01_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Identity  •  Scalable Network Segmentation"
            }
        },
        "viz_card_01_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Tracks TrustSec\\-tagged ISE authentication activity by site over time and retains the SGT/site rollup as drill\\-down detail\\."
            }
        },
        "viz_card_01_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> sparklineValues | lastPoint()",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "percent",
                "shouldAbbreviateTrendValue": true,
                "showTrendIndicator": true,
                "sparklineValues": "> primary | seriesByName(\"BucketTotal\")",
                "trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
                "trendFontSize": 28,
                "trendValue": "> sparklineValues | delta(-2)"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#f7782f",
                        "to": -0.000001
                    },
                    {
                        "value": "#a6adb6",
                        "from": -0.000001,
                        "to": 0.000001
                    },
                    {
                        "value": "#4cbf7f",
                        "from": 0.000001
                    }
                ]
            }
        },
        "viz_card_01_trend": {
            "type": "splunk.area",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "seriesColors": [
                    "#9b5ff4",
                    "#3abdfa",
                    "#0d8e97",
                    "#e2a811",
                    "#e44273",
                    "#a9afda",
                    "#d8580f",
                    "#f88ddc",
                    "#159352",
                    "#9abe2d",
                    "#6574f3",
                    "#ff9297",
                    "#d14baf",
                    "#24c4c9",
                    "#bb6e04",
                    "#6ec641",
                    "#777daf",
                    "#ff9755",
                    "#698c07",
                    "#c69fff"
                ],
                "dataValuesDisplay": "minmax",
                "lineWidth": 3,
                "markerDisplay": "outlined",
                "nullValueDisplay": "connect",
                "showYMajorGridLines": true,
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"_time\")",
                "y": "> primary | seriesByName(\"BucketTotal\")"
            }
        },
        "viz_card_01_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
